import{z as o,x as r,o as e,c as s,q as t,j as B,D as a,d as l,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"技能形成的一生","description":"","frontmatter":{"title":"技能形成的一生","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-skill-formation.md","filePath":"econ/ed2-skill-formation.md","lastUpdated":1791413859000}'),d={name:"econ/ed2-skill-formation.md"};function _(c,E,p,h,m,D){const A=r("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="技能形成的一生" tabindex="-1">技能形成的一生 <a class="header-anchor" href="#技能形成的一生" aria-label="Permalink to &quot;技能形成的一生&quot;">​</a></h1><div class="epigraph"><p>技能形成的经济学是时序的经济学：同样一美元，砸在四岁与砸在四十岁，买到的不是同一种技能。</p><footer>—— 据 Cunha and Heckman, QJE 2007；Heckman 等, Journal of Public Economics 2010 整理</footer></div><p><a href="/econ/ed2-higher-ed">上一课</a>把十八岁那笔投资算清；本课把时间轴拉长——技能不是十八岁一次成型的存货，而是从幼儿期一路滚动的存量。<a href="/econ/human-capital-becker">人力资本</a>的租期效应早就预言投资该趁早，可经验证据凑成了三个互相打架的读数，需要一个能同时容纳它们的记忆模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个事实拼在一张桌上。其一，租期效应：同样的技能，二十五岁学有四十年收租，投资应前密后疏。其二，分数消退：早期干预抬高的测验分数，几年内衰减殆尽——Project STAR 的小班红利在高中前基本消失（<a href="/econ/ca-education-causal">教育中的因果问题</a>）。其三，成年不消退：同样的干预，成年后的收入、就业与犯罪却留下了稳定差异，佩里学前班是范本。静态生产函数无法同时读这三条：分数是产出，它消退了，效应怎么可能还在？</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Cunha–Heckman 2007 的技术是本课的记忆装置：</p> \\[\\theta_{t+1} = f_t(\\theta_t, I_t), \\qquad \\frac{\\partial f_t}{\\partial \\theta_t} \\gt 0, \\qquad \\frac{\\partial^2 f_t}{\\partial \\theta_t \\, \\partial I_t} \\gt 0. \\]<p>技能向量 \\(\\theta\\)（认知 \\(\\theta^C\\) 与非认知 \\(\\theta^N\\) 两维互相喂养）带着自生产性质：今天的存量本身就是明天的投入。<span class="marginnote">术语翻译：「自生产」就是技能自己滚雪球——今天学的成为明天学习的原料：词汇多的人读得快，读得快又认识更多词。「动态互补」则说雪球越大粘得越多：存量高时，同样的练习产出更高。</span>动态互补：存量越高，同样投入的边际产出越大。加上测量口径的关键修正——测验分数只读认知一维，而干预挪动的是整个向量，向量被生产函数存住，到成年才在收入里兑现。</p>',9)),(e(),B(n,null,{default:a(()=>[i(A,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%B9%BC%E5%84%BF%E6%9C%9F%E6%8A%95%E5%85%A5%20I_1%22%5D%20--%3E%20T1%5B%22%E6%8A%80%E8%83%BD%E5%90%91%E9%87%8F%20%CE%B8_1%22%5D%0A%20%20T1%20--%3E%20S%5B%22%E5%AD%A6%E9%BE%84%E6%9C%9F%E6%8A%95%E5%85%A5%20I_2%22%5D%0A%20%20S%20--%3E%20T2%5B%22%E6%8A%80%E8%83%BD%E5%90%91%E9%87%8F%20%CE%B8_2%EF%BC%9A%E8%87%AA%E7%94%9F%E4%BA%A7%20%2B%20%E5%8A%A8%E6%80%81%E4%BA%92%E8%A1%A5%22%5D%0A%20%20T2%20--%3E%20H%5B%22%E9%AB%98%E7%AD%89%E6%95%99%E8%82%B2%E4%B8%8E%E5%9F%B9%E8%AE%AD%22%5D%0A%20%20H%20--%3E%20T3%5B%22%E8%81%8C%E5%9C%BA%E5%AD%98%E9%87%8F%20%CE%B8_3%22%5D%0A%20%20T2%20-.%E5%88%86%E6%95%B0%E4%BB%A3%E7%90%86%EF%BC%9A%E5%8F%AA%E8%AF%BB%E8%AE%A4%E7%9F%A5%E4%B8%80%E7%BB%B4.-%3E%20SC%5B%22%E6%B5%8B%E9%AA%8C%E5%88%86%E6%95%B0%EF%BC%9A%E4%BC%9A%E6%B6%88%E9%80%80%22%5D%0A%20%20T3%20--%3E%20LR%5B%22%E6%94%B6%E5%85%A5%E3%80%81%E5%B0%B1%E4%B8%9A%E3%80%81%E7%8A%AF%E7%BD%AA%EF%BC%9A%E4%B8%8D%E6%B6%88%E9%80%80%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>动态互补一次解掉全部三个谜。分数消退而收入不消退：消退的是认知一维的代理，被存住的是非认知维度与向量间的喂养——佩里项目里，处理组与对照的 IQ 差几年内消失，四十岁时的收入与就业差却显著，Heckman 等 2010 把它折成年回报率约 7%–10%，主要渠道正是软技能（计划、坚持、协作）压低了犯罪与提升了劳动市场表现。<span class="marginnote">数字实例：年回报率 7%–10%，一美元按复利滚四十年约变成 15–45 美元——不低于股市长期年化回报，而这个项目「赚」的主要不是分数，是少犯罪、多就业省下与挣出的钱。</span>趁早的机制不是「幼儿学得快」，而是互补：早期技能降低后期一切学习的边际成本，skill begets skill——同样的钱在后面是补救，在前面是杠杆。政策含义因此倒转常见直觉：成人再培训的高成本低回报不是执行失败，而是生产函数的性质；补救式投入买的是替代品，发展式投入买的是乘数。<span class="marginnote">常见误区：「早期教育就是提前学知识」。模型里早期投入买的是整个向量——含计划、坚持、协作这些非认知技能；IQ 差几年就追平，四十年后拉开差距的是这些「软」维度。把学前班办成知识抢跑，恰好买错了维度。</span></p><p><span class="marginnote">佩里学前班的特别之处在于它不是靠分数赢的：随机分组的 IQ 优势在小学阶段就不再显著，收益在四十年后的税表与犯罪记录里——这是「分数是代理、向量才是产出」最完整的一份档案。</span></p><p>同一美元投在年龄轴的两端，走的是两条完全不同的回报路径。</p>',4)),(e(),B(n,null,{default:a(()=>[i(A,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%90%8C%E6%A0%B7%E4%B8%80%E7%BE%8E%E5%85%83%22%5D%20--%3E%20A%7B%22%E6%8A%95%E5%9C%A8%E5%93%AA%E4%B8%AA%E5%B9%B4%E9%BE%84%E6%AE%B5%22%7D%0A%20%20A%20--%3E%7C%22%E5%9B%9B%E5%B2%81%3A%20%E5%AD%98%E9%87%8F%E4%BD%8E%E4%BD%86%E4%BA%92%E8%A1%A5%E5%BC%BA%22%7C%20Y%5B%22%E6%8A%AC%E9%AB%98%E6%95%B4%E4%B8%AA%E6%8A%80%E8%83%BD%E5%90%91%E9%87%8F%22%5D%0A%20%20Y%20--%3E%20LEV%5B%22%E6%9D%A0%E6%9D%86%3A%20%E5%90%8E%E7%BB%AD%E4%B8%80%E5%88%87%E6%8A%95%E5%85%A5%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20A%20--%3E%7C%22%E5%9B%9B%E5%8D%81%E5%B2%81%3A%20%E8%A1%A5%E6%95%91%E5%BC%8F%E5%86%8D%E5%9F%B9%E8%AE%AD%22%7C%20O%5B%22%E7%BB%95%E8%BF%87%E4%BD%8E%E5%AD%98%E9%87%8F%E8%A1%A5%E6%8A%80%E8%83%BD%22%5D%0A%20%20O%20--%3E%20SUB%5B%22%E6%9B%BF%E4%BB%A3%E5%93%81%3A%20%E6%88%90%E6%9C%AC%E9%AB%98%2C%20%E5%9B%9E%E6%8A%A5%E8%96%84%22%5D%0A%20%20LEV%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%E6%97%B6%E5%BA%8F%3A%20%E5%8F%91%E5%B1%95%E5%BC%8F%E4%BC%98%E5%85%88%E4%BA%8E%E8%A1%A5%E6%95%91%E5%BC%8F%22%5D%0A%20%20SUB%20--%3E%20POL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>「越早越好」是准实验证据的汇总形态，不是物理常数：复制研究在不同人群里大小不一，规模化会稀释佩里式小样本项目的高强度。动态模型的识别依赖强假设——测量方程、遗漏的父母投入、非认知技能的粗糙度量都在留有余地。干预的窗口也不是唯一：青春期是另一个敏感期，证据还在追加。最后，从个体技能到<a href="/econ/intergenerational-mobility">代际流动与人力资本</a>只有一步——父母投资孩子，本课的技术函数就是那道代际传送带的机械图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>技术函数 \\(\\theta_{t+1} = f_t(\\theta_t, I_t)\\) 的两条性质：自生产与动态互补，是全课的发动机。</li><li>分数消退、收入不消退：代理只读认知一维，被存住的是技能向量与非认知维度。</li><li>佩里项目年回报率约 7%–10%，渠道是软技能压犯罪、提就业，不是 IQ。</li><li>skill begets skill：早期投入是乘数，后期补救是替代品——政策时序由此定。</li><li>出处：Cunha and Heckman, QJE 2007；Heckman 等, Journal of Public Economics 2010；Chetty 等, QJE 2011。</li></ul>',4))])}const u=o(d,[["render",_]]);export{f as __pageData,u as default};
